using MunicipalPlatform.Api.Platform.Tenancy;
namespace MunicipalPlatform.Api.Modules.Gazette.Domain;

public sealed class GazetteCorrection : ITenantEntity { private GazetteCorrection() { } public GazetteCorrection(Guid municipalityId, Guid originalEditionId, Guid correctionEditionId, string reason, Guid actorId) { Id = Guid.NewGuid(); MunicipalityId = municipalityId; OriginalEditionId = originalEditionId; CorrectionEditionId = correctionEditionId; Reason = reason.Trim(); CreatedBy = actorId; CreatedAt = DateTimeOffset.UtcNow; } public Guid Id { get; private set; } public Guid MunicipalityId { get; private set; } public Guid OriginalEditionId { get; private set; } public Guid CorrectionEditionId { get; private set; } public string Reason { get; private set; } = string.Empty; public Guid CreatedBy { get; private set; } public DateTimeOffset CreatedAt { get; private set; } }
